+    // Gemini reports running totals in every chunk, while usage delta chunks
+    // are summed, so emit only the growth since the previous chunk.
+    const reasoningTokens =
+      usage.thoughtsTokenCount ?? /* v8 ignore next 1 */ 0;
+    const current = {
